ltac2:(KReplay.run1 (kr_t_RF_huf_bdt_bld ()) [] "p'0h02H0h11ni001nh22H1h31li011lh42Hlh52Hxh61vh71eh81Hh92Hvh:2H2h;2IHh<1Ph=2l0h>1xi021xh?2x0h@1zi031zp;1p;3p;2p;6p;5g0030R0j1ATg00g8j34Tg007Lj1;Tg01fbj28Tg009Bj31Tg000Mj6=Tg009\j2<Tg01gCj65Tg01g`j67Tg005Vj1:Tg001Uj69Tg00<Pj2@Tg00PCj5?Tg01hAR1j36Tg007lj3>Tg00UUR2f1R3f0R436p=2f3R5f2R6?434562p=3A>234p=0p-0R7\2%A2R8P2g00U6R9f4R:/26f5R;P3O1f6R<A456:R='2[[^62]1X38%;2R>,25P:P3O1P9P<P4P5P>C3P5182;f7R?,82X19P4O1n0110000020010100W9W8X62X1912;6P<P3O112?=[[^62^1910:5R=,2<P?P3O1P1P2f8R1101?R@9183f;RAP<P;f9RB/01C3RC[P310<;RD918>10?<RE918>P8P>P0P2P7P4g00]Bg00\eR7n10110100020020000000X78g00]^P@P4E=P71<C4b2W0P4O1W0f>RCP3O1f?R7/231056f=,0C518107C918=P8P8P0P2P8P4P;P4n10110100020020103101X7810;:f@R=/07P4E5A18:7P8P2P0P2P2P4P?P3n10110100020020103101X78PDfAR0/0=P3E5A12<0fBR0912?P4fCR?9121P2fDR<A18B<R=fHR7P3O1fIRC/2AfJRAfER>P<fGRF,07RGC3]4]5[X@2A181?P4P=P8P>PCPFO112A3fKR=fFR?P>10C7R1C3]4]5X38P7P?O112C?P9P=P4P>P1C3P>P2PAP<PFP0P4E7PAg00V3P<PGC3eP2fLRGPAA44?CP5P7P4P?P6P<O4E7PG%:4P?10ACC3eX19P4O1n0110000020010100W4W5f:RAP4E9b:W2PBP4E9b2W0P4O1b2P4O1b2W0P4P6P3O3W0W4W5X=8X?2P5P6P3P4O4n200210100000020041102101000000A184EPAP;P:P@C3[X38PDO1P41@8EO1b0W9W8X62X19W;X38X>2P4D?W3W<o"). Qed.

Ltac bl_ck := let K := fresh "KC" in
  if_cases K; zify_cond K;
  [exfalso; rewrite ?zb_lxor_ones in K by lia; Z.div_mod_to_equations; lia | clear K].

Section Build.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x8 x9 x16 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 : word).
  Variables (m : fmem) (TD WK : Z) (tl M1 : Z) (jt : list byte) (syms : list (option Z)).
  Variable POST : machine_state -> Prop.
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HM1 : 1 <= M1 <= 256.
  Hypothesis HJT : length jt = (4 * Z.to_nat (2^tl))%nat.
  Hypothesis HSL : length syms = Z.to_nat (2^tl).
  Hypothesis HTD : 0 < TD /\ TD + 4 * 2^tl <= 2^64.
  Hypothesis HWK : 0 < WK /\ WK + 2 * M1 <= 2^64.
  Hypothesis DTW : TD + 4 * 2^tl <= WK \/ WK + 2 * M1 <= TD.

  Definition bl_inv (m1 : fmem) (u : Z) (snext : list Z) (acc : list dcell) : Prop :=
    u8arr usegs m1 TD (concat (map fse_cell_bytes acc) ++ tsym (skipn (4 * Z.to_nat u) jt) (skipn (Z.to_nat u) syms))
    /\ u8arr usegs m1 WK (u16s (map (Z_to_bv 64) snext))
    /\ munch [(TD, TD + 4 * 2^tl); (WK, WK + 2 * M1)] m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

  Definition bl_sep (s : Z) : Prop :=
    (s + 24 <= TD \/ TD + 4 * 2^tl <= s + 16) /\ (s + 24 <= WK \/ WK + 2 * M1 <= s + 16).

  Notation ST pc mm x10 x13 x16 x28 x29 x30 x31 :=
    (MS (mkR ra sp gp tp (Z_to_bv 64 252645135) (Z_to_bv 64 16843009) (Z_to_bv 64 31) x8 x9 x10
             (Z_to_bv 64 1431655765) (Z_to_bv 64 858993459) x13 (Z_to_bv 64 WK) (Z_to_bv 64 (2^tl))
             x16 (Z_to_bv 64 TD)
             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom usegs)).

  Lemma bl_loop : forall f u snext acc r m1 (w13 w30 w31 : word),
    build_loop tl f u syms snext acc = Ok r ->
    Z.of_nat f = 2^tl - u -> 0 <= u < 2^tl -> zlen acc = u -> zlen snext = M1 ->
    Forall (fun v => 0 <= v < 65536) snext ->
    bl_sep (bv_unsigned sp) ->
    rw_cells usegs m1 (bv_unsigned sp + 16) [C8 (Z_to_bv 64 tl)] ->
    bl_inv m1 u snext acc ->
    (forall m2 snext' (y10 y13 y28 y29 y30 y31 : word), zlen r = 2^tl -> bl_inv m2 (2^tl) snext' r ->
       rw_cells usegs m2 (bv_unsigned sp + 16) [C8 (Z_to_bv 64 tl)] ->
       evt usegs POST (ST 0x1f5f4 m2 y10 y13 (Z_to_bv 64 0) y28 y29 y30 y31)) ->
    evt usegs POST (ST 0x1f53c m1 (Z_to_bv 64 (TD + 3 + 4 * u)) w13 (Z_to_bv 64 (Z.lxor WK 18446744073709551615)) (Z_to_bv 64 (2^tl - u)) (Z_to_bv 64 (TD + 4 * u)) w30 w31).
Proof using All.
  induction f as [|f IH]; intros until w31; intros RL HF HU HA HS HSR SEP SLT INV KONT; [exfalso; lia|].
  destruct INV as (TA & WA & MU & WM & MI).
  cbn [build_loop] in RL.
  destruct (bind_Ok_inv _ _ _ RL) as (sym & OL & RL1). apply oload_Ok in OL. destruct OL as (SYR & SYN).
  destruct (bind_Ok_inv _ _ _ RL1) as (ns & LD & RL2). apply load_Ok in LD. destruct LD as (NSI & NSE).
  destruct (bind_Ok_inv _ _ _ RL2) as (sn2 & SO & RL3). apply store_Ok in SO. destruct SO as (_ & SNE).
  destruct (bind_Ok_inv _ _ _ RL3) as (hb & HB & RL4).
  destruct (bind_Ok_inv _ _ _ RL4) as (sh & SH & RL5).
  repeat (first [ bl_ck | zstep ]).
  assert (TL4 : length jt = (4 * length syms)%nat) by lia.
  destruct (tsym_at syms jt (Z.to_nat u) sym TL4 SYN) as (j0 & j1 & j3 & TS).
  rewrite TS in TA.
  assert (PL : length (concat (map fse_cell_bytes acc)) = (4 * Z.to_nat u)%nat) by (rewrite fse_cells_length; lia).
  lazymatch goal with |- _ => let a := cur_mem_addr in
    pose proof (u8arr_read usegs m1 TD _ (4 * u + 2) (Z_to_bv 8 sym) a TA ltac:(apply nth_cell2; lia) ltac:(lia) ltac:(addr_tac)) as RD end.
  zstep.
  cbv beta. rewrite ?(unsigned_byte sym) by lia.
  zstep. rewrite ?(Z.mod_small (sym ≪ 1) 18446744073709551616) by (rewrite Z.shiftl_mul_pow2 by lia; lia).
  try replace (sym ≪ 1) with (2 * sym) by (rewrite Z.shiftl_mul_pow2 by lia; lia).
  repeat (first [ bl_ck | zstep ]).
  assert (NSR : 0 <= ns < 65536) by (rewrite NSE; unfold Znth; apply (proj1 (Forall_forall _ _) HSR); apply nth_In; lia).
  lazymatch goal with |- _ => let a := cur_mem_addr in
    pose proof (u16_znth usegs m1 WK snext sym a (proj1 WA) ltac:(lia) ltac:(addr_tac)) as RD2 end.
  rewrite <- NSE in RD2.
  zstep.
  rewrite ?(zx16_lit ns) by lia.
  repeat (first [ bl_ck | zstep ]).
  assert (LSN : length (map (Z_to_bv 64) snext) = length snext) by (rewrite length_map; reflexivity).
  pose proof (u16arr_store_ok usegs _ WK _ sym (wa (WK + 2 * sym)) WA ltac:(rewrite LSN; lia) eq_refl) as SOK.
  zstep.
  rewrite (le2_eqm16 (ns + 1) (u16 (ns + 1))) by (unfold u16; Z.div_mod_to_equations; lia).
  pose proof (u16arr_write usegs _ WK _ sym (Z_to_bv 64 (u16 (ns + 1))) WA ltac:(rewrite LSN; lia)) as WA2.
  lazymatch type of TA with u8arr _ _ _ ?bs =>
    assert (LTB : Z.of_nat (length bs) = 4 * 2^tl) by (rewrite !length_app, tsym_length, length_skipn, PL; cbn [length]; lia) end.
  pose proof SEP as SDP. unfold bl_sep in SDP. destruct SDP as [SD1 SD2].
  pose proof (u8arr_frame usegs m1 TD _ (WK + 2 * sym) (le2 (Z_to_bv 64 (u16 (ns + 1)))) TA ltac:(lia) ltac:(rewrite length_le2; lia) ltac:(rewrite LTB, length_le2; lia)) as TA2.
  pose proof (rw_cells_frame usegs m1 (bv_unsigned sp + 16) _ (WK + 2 * sym) (le2 (Z_to_bv 64 (u16 (ns + 1)))) SLT ltac:(lia) ltac:(rewrite length_le2; lia) ltac:(cbn [cells_size csize]; rewrite length_le2; lia)) as SLT2.
  clear WA TA SLT SD1 SD2. store_done.
  rewrite <- map_Zupd in WA2 by lia. rewrite <- SNE in WA2.
  unfold highbit32 in HB. destruct ((0 <? ns) && (ns <? 2^32)) eqn:HBC; [|discriminate].
  injection HB as HB. apply andb_true_iff in HBC. destruct HBC as [HB1 HB2]. apply Z.ltb_lt in HB1, HB2.
  unfold shl32 in SH. destruct ((0 <=? to_byte (tl - hb)) && (to_byte (tl - hb) <? 32)) eqn:SHC; [|discriminate].
  injection SH as SH. apply andb_true_iff in SHC. destruct SHC as [SH1 SH2]. apply Z.leb_le in SH1. apply Z.ltb_lt in SH2.
  repeat (first [ bl_ck | zstep ]).
  set (s3 := Z.lor (Z.lor (Z.lor ns (ns ≫ 1)) ((Z.lor ns (ns ≫ 1)) ≫ 2)) ((Z.lor (Z.lor ns (ns ≫ 1)) ((Z.lor ns (ns ≫ 1)) ≫ 2)) ≫ 4)) in *.
  assert (S3 : s3 = sm3 ns) by reflexivity.
  assert (S3R : 0 <= s3 < 65536) by (rewrite S3; apply sm3_lt; lia).
  rewrite ?(shl48_shr56 s3 S3R).
  assert (S4 : Z.lor s3 (s3 ≫ 8) = Z.ones (Z.log2 ns + 1)) by (rewrite S3; apply (sm4_ones ns); lia).
  rewrite ?S4. subst hb. clearbody s3. clear S3 S4.
  set (L := Z.log2 ns) in *.
  assert (HL : 0 <= L <= 15).
  { subst L. split; [apply Z.log2_nonneg|]. assert (Z.log2 ns < 16); [|lia]. apply Z.log2_lt_pow2; [lia|]. change (2^16) with 65536. lia. }
  unfold to_byte in SH1, SH2.
  assert (TLL : 0 <= tl - L) by (clear - SH1 SH2 HL HTL; Z.div_mod_to_equations; lia).
  lazymatch goal with |- _ => let v := reg_val 13 in lazymatch v with Z_to_bv 64 (bv_swrap _ (_ - Z.lxor ?x ?c)) =>
    replace (Z.lxor x c) with L by (clear - HL; clearbody L;
      assert (C : L = 0 \/ L = 1 \/ L = 2 \/ L = 3 \/ L = 4 \/ L = 5 \/ L = 6 \/ L = 7 \/ L = 8 \/ L = 9 \/ L = 10 \/ L = 11 \/ L = 12 \/ L = 13 \/ L = 14 \/ L = 15) by lia;
      repeat (destruct C as [E|C]; [rewrite E; vm_compute; reflexivity|]); rewrite C; vm_compute; reflexivity) end end.
  rewrite (swrap32_small (tl - L)) by lia.
  repeat (first [ bl_ck | zstep ]).
  pose proof (u8arr_store_ok usegs _ TD _ (4 * u + 3) (wa (TD + 3 + 4 * u)) TA2 ltac:(rewrite LTB; lia) ltac:(unfold wa; f_equal; lia)) as SOK2.
  zstep.
  rewrite ?le1_lit.
  pose proof (u8arr_write usegs _ TD _ (4 * u + 3) (Z_to_bv 8 (tl - L)) TA2 ltac:(rewrite LTB; lia)) as TA3.
  replace (TD + (4 * u + 3)) with (TD + 3 + 4 * u) in TA3 by lia.
  assert (WKD : WK + 2 * M1 <= TD + 3 + 4 * u \/ TD + 3 + 4 * u + 1 <= WK) by (clear - DTW HU HTD HWK; lia).
  assert (HSN : Z.of_nat (length snext) = M1) by exact HS.
  lazymatch type of WA2 with u8arr _ _ _ ?bs => assert (LWB : Z.of_nat (length bs) = 2 * M1) by (rewrite u16s_length, length_map, SNE, Zupd_length; lia) end.
  pose proof (u8arr_frame usegs _ WK _ (TD + 3 + 4 * u) [Z_to_bv 8 (tl - L)] WA2 ltac:(lia) ltac:(cbn [length]; lia) ltac:(rewrite LWB; cbn [length]; lia)) as WA3.
  pose proof (rw_cells_frame usegs _ (bv_unsigned sp + 16) _ (TD + 3 + 4 * u) [Z_to_bv 8 (tl - L)] SLT2 ltac:(lia) ltac:(cbn [length]; lia) ltac:(cbn [cells_size csize length]; pose proof SEP as SDP; unfold bl_sep in SDP; lia)) as SLT3.
  clear TA2 WA2 SLT2. store_done.
  replace (Z.to_nat (4 * u + 3)) with (length (concat (map fse_cell_bytes acc)) + 3)%nat in TA3 by lia.
  rewrite cell_write_nb in TA3.
  repeat (first [ bl_ck | zstep ]).
  let K := fresh "KC" in if_cases K; zify_cond K;
    [exfalso; rewrite (Z.mod_small (tl - L)) in K by lia; change 255 with (Z.ones 8) in K; rewrite Z.land_ones, Z.mod_small in K by lia; lia | clear K].
  repeat (first [ bl_ck | zstep ]).
  lazymatch type of TA3 with u8arr _ _ _ ?bs =>
    assert (LT3 : Z.of_nat (length bs) = 4 * 2^tl) by (rewrite !length_app, tsym_length, length_skipn, PL; cbn [length]; lia) end.
  pose proof (u8arr_store_ok_n usegs _ TD _ (4 * u) 2 (wa (TD + 3 + 4 * u + -3)) TA3 ltac:(lia) ltac:(rewrite LT3; lia) ltac:(unfold wa; f_equal; lia)) as SOK3.
  zstep.
  unfold to_byte in SH. rewrite (Z.mod_small (tl - L)) in SH by lia.
  lazymatch goal with |- context [le2 (Z_to_bv 64 ?x)] =>
    rewrite (le2_eqm16 x (u16 (sh - 2^tl))) by (rewrite ns_mod16; rewrite (Z.mod_small (tl - L)) by lia; change 255 with (Z.ones 8);
      rewrite Z.land_ones by lia; rewrite (Z.mod_small (tl - L) (2^8)) by lia; rewrite shiftl_mod32 by lia; rewrite SH; reflexivity) end.
  pose proof (u8arr_write_bytes usegs _ TD _ (4 * u) (le2 (Z_to_bv 64 (u16 (sh - 2^tl)))) TA3 ltac:(lia) ltac:(rewrite length_le2; lia)) as TA4.
  replace (TD + 4 * u) with (TD + 3 + 4 * u + -3) in TA4 by lia.
  pose proof (u8arr_frame usegs _ WK _ (TD + 3 + 4 * u + -3) (le2 (Z_to_bv 64 (u16 (sh - 2^tl)))) WA3 ltac:(lia) ltac:(rewrite length_le2; lia) ltac:(rewrite LWB, length_le2; clear - DTW HU HTD HWK; lia)) as WA4.
  pose proof (rw_cells_frame usegs _ (bv_unsigned sp + 16) _ (TD + 3 + 4 * u + -3) (le2 (Z_to_bv 64 (u16 (sh - 2^tl)))) SLT3 ltac:(lia) ltac:(rewrite length_le2; lia) ltac:(cbn [cells_size csize]; rewrite length_le2; pose proof SEP as SDP; unfold bl_sep in SDP; lia)) as SLT4.
  clear TA3 WA3 SLT3. store_done.
  replace (Z.to_nat (4 * u)) with (length (concat (map fse_cell_bytes acc))) in TA4 by lia.
  rewrite cell_write_ns in TA4.
  lazymatch type of TA4 with u8arr _ ?mm _ _ =>
    assert (TA5 : u8arr usegs mm TD (concat (map fse_cell_bytes (acc ++ [mkDC (u16 (sh - 2^tl)) sym (to_byte (tl - L))])) ++ tsym (skipn (4 * Z.to_nat (u + 1)) jt) (skipn (Z.to_nat (u + 1)) syms))) end.
  { rewrite fse_cells_snoc. replace (Z.to_nat (u + 1)) with (S (Z.to_nat u)) by lia.
    replace (fse_cell_bytes (mkDC (u16 (sh - 2^tl)) sym (to_byte (tl - L)))) with (le2 (Z_to_bv 64 (u16 (sh - 2^tl))) ++ [Z_to_bv 8 sym; Z_to_bv 8 (to_byte (tl - L))]) by reflexivity.
    unfold to_byte; rewrite (Z.mod_small (tl - L)) by lia. rewrite <- !app_assoc in TA4 |- *. exact TA4. }
  clear TA4.
  repeat (first [ bl_ck | zstep ]).
  assert (SN2L : zlen sn2 = M1) by (rewrite SNE; unfold Zupd; rewrite upd_nat_length; lia).
  let K := fresh "KC" in if_cases K; zify_cond K.
  - let v := reg_val 10 in replace v with (Z_to_bv 64 (TD + 3 + 4 * (u + 1))) by (f_equal; lia).
    let v := reg_val 28 in replace v with (Z_to_bv 64 (2^tl - (u + 1))) by (f_equal; lia).
    let v := reg_val 29 in replace v with (Z_to_bv 64 (TD + 4 * (u + 1))) by (f_equal; lia).
    eapply (IH (u + 1) sn2 (acc ++ [mkDC (u16 (sh - 2^tl)) sym (to_byte (tl - L))]) r).
    + exact RL5.
    + lia.
    + lia.
    + rewrite length_app; cbn [length]; lia.
    + exact SN2L.
    + rewrite SNE; unfold Zupd; apply Forall_upd_nat; [exact HSR | unfold u16; Z.div_mod_to_equations; lia].
    + exact SEP.
    + exact SLT4.
    + unfold bl_inv; split; [exact TA5|]; split; [exact WA4|]; repeat split; assumption.
    + exact KONT.
  - destruct f as [|f]; [|exfalso; lia]. cbn [build_loop] in RL5. injection RL5 as RL5.
    zstep.
    eapply (KONT _ sn2).
    + rewrite <- RL5, length_app; cbn [length]; lia.
    + replace (2^tl) with (u + 1) by lia. rewrite <- RL5. unfold bl_inv; split; [exact TA5|]; split; [exact WA4|]; repeat split; assumption.
    + exact SLT4.
Qed.
End Build.
